public static class Validation {
 [Serializable] public class Part {public string key,slot,role;}
 [Serializable] public class Weights {public string name;public float[] times,left,right,first;}
 [Serializable] public class Job {public string name,body,animation,source,game,handKey;public string[] loadOrder,skinBones,clips;public Part[] parts;public Weights[] weights;public bool probeOnly=true;public float sheetT0=0,sheetT1=1,sheetSize=.48f;public Vector3 sheetLook=new Vector3(0,-.33f,0);public string[] sheetViews;}
 [Serializable] public class Sample {public float time,leftGripWeight,rightGripWeight,leftSurfaceMm,magPalmMm,rightStockSphereMm,thumbSelectorMm,ikErrorMm,magPenetrationLowerMm,magPenetrationUpperMm;public int collisionUnresolved;public float magWellOutsideMm,magTopAboveEntryMm;public Vector3 rPalmPushStockLocal;public float rPalmStockGapMm,rFingerStockGapMm;public float lHandGuardGapMm,lHandMagGapMm,lHandPenMm,rHandStockGapMm,rHandPenMm,rThumbTipSelectorMm;}
 [Serializable] public class ClipResult {public string name;public List<Sample> frames=new List<Sample>();}
 [Serializable] public class Report {public bool complete,geometrySelfTest;public string error;public string name;public int mappedSkinBones,skinVertices;public List<string> topology=new List<string>();public List<ClipResult> clips=new List<ClipResult>();public List<string> renders=new List<string>();}
 static Job job;static Report report;static string output;static GameObject model,skin;static Transform weapon;static Dictionary<string,Transform> rig;static Dictionary<string,AssetBundle> loaded=new Dictionary<string,AssetBundle>();static Dictionary<string,List<Geometry>> geo=new Dictionary<string,List<Geometry>>();static Dictionary<Transform,(Vector3,Quaternion,Vector3)> rest;static GripPose[] grips;static MeshRenderer[] staticRenderers;
 static string Arg(string n){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,n);return i<0?null:a[i+1];}
 static Transform Find(string n)=>rig.ContainsKey(n)?rig[n]:model.GetComponentsInChildren<Transform>(true).First(t=>t.name==n);
 static AssetBundle Load(string key){if(loaded.ContainsKey(key))return loaded[key];string p=Path.Combine(job.source??"",key);if(!File.Exists(p))p=Path.Combine(job.game,key);var b=AssetBundle.LoadFromFile(p);if(!b)throw new Exception("Cannot load "+p);loaded[key]=b;return b;}
 static Dictionary<string,Mesh> exported=new Dictionary<string,Mesh>();
 static Mesh Exported(Mesh src){if(exported.TryGetValue(src.name,out var m))return m;var path=Path.Combine(Arg("-k2Meshes"),src.name+".bin");if(!File.Exists(path)){if(src.isReadable)return src;throw new Exception("메시 추출본 없음 "+src.name);}using(var br=new BinaryReader(File.OpenRead(path))){int nv=br.ReadInt32(),ni=br.ReadInt32();var v=new Vector3[nv];for(int i=0;i<nv;i++)v[i]=new Vector3(br.ReadSingle(),br.ReadSingle(),br.ReadSingle());var idx=new int[ni];for(int i=0;i<ni;i++)idx[i]=br.ReadInt32();m=new Mesh{name=src.name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32,vertices=v,triangles=idx};}if(src.isReadable){var sv=src.vertices;float d=0;for(int i=0;i<Mathf.Min(sv.Length,m.vertexCount);i+=7)d=Mathf.Max(d,(sv[i]-m.vertices[i]).magnitude);report.topology.Add("추출 대조 "+src.name+" 정점 "+sv.Length+"/"+m.vertexCount+" 최대차 "+(d*1000).ToString("F3")+"mm");}exported[src.name]=m;return m;}
 static int debugCount;
 static string V3(Vector3 v)=>v.ToString("F3");
 static HashSet<string> logged=new HashSet<string>();
 static string Path_(Transform t){var n=t.name;while(t.parent&&t.parent!=model.transform){t=t.parent;n=t.name+"/"+n;}return n;}
 static int Depth(Transform t){int n=0;while(t.parent){t=t.parent;n++;}return n;}
 static List<Geometry> GeometryFor(GameObject root){var list=new List<Geometry>();var lods=root.GetComponentsInChildren<LODGroup>(true);var omitted=new HashSet<Renderer>();foreach(var lod in lods){var all=lod.GetLODs();foreach(var l in all.Skip(1))foreach(var r in l.renderers)if(r)omitted.Add(r);if(all.Length>0)foreach(var r in all[0].renderers)omitted.Remove(r);lod.ForceLOD(0);}foreach(var mf in root.GetComponentsInChildren<MeshFilter>(true)){var mr=mf.GetComponent<Renderer>();if(!mf.sharedMesh||mf.sharedMesh.vertexCount==0||omitted.Contains(mr)||System.Text.RegularExpressions.Regex.IsMatch(mf.name,"LOD[1-9]"))continue;var g=new Geometry(Exported(mf.sharedMesh),mf.transform);list.Add(g);report.topology.Add(mf.name+" vertices="+g.vertices.Length+" boundary="+g.boundaryEdges+" nonmanifold="+g.nonManifoldEdges);}return list;}
 static void Setup(){foreach(var key in job.loadOrder)Load(key);var wp=Load(job.body).LoadAllAssets<GameObject>().Select(g=>g.GetComponent<WeaponPrefab>()).Single(w=>w!=null);model=UnityEngine.Object.Instantiate(wp._weaponObject);model.GetComponent<Animator>().enabled=false;rig=model.GetComponentsInChildren<Transform>(true).GroupBy(t=>t.name).ToDictionary(g=>g.Key,g=>g.First());weapon=Find("weapon");
 geo["solid"]=GeometryFor(model);geo["handguard"]=new List<Geometry>();geo["magazine"]=new List<Geometry>();geo["stock"]=new List<Geometry>();geo["selector"]=GeometryFor(Find("weapon_selector").gameObject);
 foreach(var part in job.parts){var prefab=Load(part.key).LoadAllAssets<GameObject>().Single();var go=UnityEngine.Object.Instantiate(prefab);var slot=Find(part.slot);go.transform.SetParent(slot,false);go.transform.localPosition=Vector3.zero;go.transform.localRotation=Quaternion.Euler(90,0,0)*prefab.transform.localRotation;geo[part.role].AddRange(GeometryFor(go));}
 grips=model.GetComponentsInChildren<GripPose>(false).Where(g=>g.GripType==GripPose.EGripType.Common||g.GripType==GripPose.EGripType.UnderbarrelWeapon).ToArray();   // 게임과 같게 활성만(Player.UpdateFirstPersonGrip)
 foreach(var g in model.GetComponentsInChildren<GripPose>(true))report.topology.Add("GripPose "+Path_(g.transform)+" hand="+g.Hand+" type="+g.GripType+" active="+g.gameObject.activeInHierarchy+" depth="+Depth(g.transform));
 var hp=Load(job.handKey).LoadAllAssets<GameObject>().Single();skin=UnityEngine.Object.Instantiate(hp);skin.transform.SetParent(model.transform,false);
 foreach(var comp in skin.GetComponentsInChildren<MonoBehaviour>(true)){if(!comp)continue;var so=new SerializedObject(comp);var paths=so.FindProperty("_bonePaths");var sr=so.FindProperty("_skinnedMeshRenderer");if(paths==null||sr==null)continue;var renderer=sr.objectReferenceValue as SkinnedMeshRenderer;if(!renderer)continue;var bones=new Transform[paths.arraySize];for(int i=0;i<bones.Length;i++){var n=paths.GetArrayElementAtIndex(i).stringValue.Split('/').Last();if(!rig.ContainsKey(n))throw new Exception("Skin bone missing "+n);bones[i]=rig[n];}renderer.bones=bones;var rootPath=so.FindProperty("_rootBonePath").stringValue.Split('/' ).Last();renderer.rootBone=Find(rootPath);renderer.updateWhenOffscreen=true;report.mappedSkinBones+=bones.Length;report.skinVertices+=renderer.sharedMesh.vertexCount;}
foreach(var g in model.GetComponentsInChildren<Transform>(true).GroupBy(t=>t.name).Where(g=>g.Count()>1&&g.Key.StartsWith("Base Human")))report.topology.Add("중복 뼈 "+g.Key+": "+string.Join(" | ",g.Select(Path_)));
 foreach(var bn in new[]{"Base HumanRPalm","Base HumanLPalm","Base HumanRForearm1"}){var t=rig[bn];report.topology.Add("뼈 경로 "+bn+": "+Path_(t));}
 if(report.mappedSkinBones<40)throw new Exception("Hand skin mapping incomplete");
 foreach(var smr in skin.GetComponentsInChildren<SkinnedMeshRenderer>(true))if(!smr.bones.All(b=>b&&rig.ContainsValue(b))){smr.enabled=false;report.topology.Add("뼈 연결 안 된 스킨 끔 "+smr.name);}
 rest=rig.Values.Distinct().ToDictionary(t=>t,t=>(t.localPosition,t.localRotation,t.localScale));staticRenderers=model.GetComponentsInChildren<MeshRenderer>(true);
 foreach(var r in model.GetComponentsInChildren<Renderer>(true)){var mats=r.sharedMaterials.Select(src=>{var m=new Material(Shader.Find("Standard"));if(src){Texture tex=null;foreach(string key in new[]{"_MainTex","_BaseMap","_DiffuseMap"})if(src.HasProperty(key)&&src.GetTexture(key)){tex=src.GetTexture(key);break;}m.mainTexture=tex;m.color=tex?Color.white:new Color(.3f,.32f,.33f);m.SetFloat("_Glossiness",.18f);}return m;}).ToArray();r.sharedMaterials=mats;}
 RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.7f,.7f,.7f);var light=new GameObject("ValidationLight").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.2f;light.transform.rotation=Quaternion.Euler(35,-35,0);SetupWell();
 }
 static void Restore(){foreach(var p in rest){p.Key.localPosition=p.Value.Item1;p.Key.localRotation=p.Value.Item2;p.Key.localScale=p.Value.Item3;}}
 static float WeightAt(Weights w,float t,float[] values){if(w==null||values==null||values.Length==0)throw new Exception("Missing first-person hand weights");int i=Array.BinarySearch(w.times,t);if(i>=0)return values[i];i=~i;if(i==0)return values[0];if(i>=values.Length)return values.Last();return Mathf.Lerp(values[i-1],values[i],Mathf.InverseLerp(w.times[i-1],w.times[i],t));}
 static float Solve(string side,Vector3 target,Quaternion rotation,float weight){var up=Find("Base Human"+side+"Upperarm");var el=Find("Base Human"+side+"Forearm1");var palm=Find("Base Human"+side+"Palm");var uq=up.rotation;var eq=el.rotation;var pq=palm.rotation;var a=up.position;var b=el.position;var c=palm.position;float l1=Vector3.Distance(a,b),l2=Vector3.Distance(b,c),dist=Vector3.Distance(a,target);var axis=(target-a).normalized;float d=Mathf.Clamp(dist,Mathf.Abs(l1-l2)+.000001f,l1+l2-.000001f);float x=(l1*l1-l2*l2+d*d)/(2*d);var pole=b-a;pole-=Vector3.Dot(pole,axis)*axis;if(pole.sqrMagnitude<1e-10f)pole=Vector3.Cross(axis,weapon.right);pole.Normalize();var bend=a+axis*x+pole*Mathf.Sqrt(Mathf.Max(0,l1*l1-x*x));up.rotation=Quaternion.FromToRotation(b-a,bend-a)*up.rotation;el.rotation=Quaternion.FromToRotation(palm.position-el.position,a+axis*d-el.position)*el.rotation;up.rotation=Quaternion.Slerp(uq,up.rotation,weight);el.rotation=Quaternion.Slerp(eq,el.rotation,weight);palm.rotation=Quaternion.Slerp(pq,rotation,weight);return Vector3.Distance(palm.position,Vector3.Lerp(c,target,weight))*1000;}
 static float Hand(string side,float weight,out float blend){int hand=side=="L"?0:1;var marker=Find("weapon_"+side+"_IK_marker");var reference=Find("weapon_"+side+"_hand_marker");var grip=grips.Where(g=>(int)g.Hand==hand).OrderByDescending(g=>g.GripType==GripPose.EGripType.UnderbarrelWeapon).ThenByDescending(g=>Depth(g.transform)).FirstOrDefault();if(!logged.Contains(side)){logged.Add(side);report.topology.Add("CHOSEN "+side+" "+(grip?Path_(grip.transform):"none"));}blend=grip?Mathf.Clamp01(1-Vector3.Distance(marker.position,reference.position)/.1f):0;
 var palm=Find("Base Human"+side+"Palm");var fingers=palm.GetComponentsInChildren<Transform>();var pose=grip?grip.transform.GetComponentsInChildren<Transform>():null;var cached=grip?grip.Fingers:null;
 for(int i=1;i<fingers.Length;i++){if(hand==1&&grip&&(i==5||i==6))continue;Quaternion gq;if(grip&&cached!=null&&cached.Length==fingers.Length)gq=cached[i];else if(grip&&pose.Length==fingers.Length)gq=pose[i].localRotation;else {if(grip)throw new Exception("Grip finger mapping mismatch "+side+" "+fingers.Length+"/"+pose.Length);continue;}fingers[i].localRotation=Quaternion.Lerp(fingers[i].localRotation,gq,blend);}
 var target=grip?Vector3.Lerp(marker.position,grip.transform.position,blend):marker.position;var rot=grip?Quaternion.Lerp(marker.rotation,grip.transform.rotation,blend):marker.rotation;
 string W(Transform t)=>V3(weapon.InverseTransformPoint(t.position));var U=Find("Base Human"+side+"Upperarm");var E=Find("Base Human"+side+"Forearm1");var P=Find("Base Human"+side+"Palm");string before=$"어깨{W(U)} 팔꿈치{W(E)} 손{W(P)} 마커{W(marker)} 기준{W(reference)} 목표{V3(weapon.InverseTransformPoint(target))} 혼합{blend:F2} 무게{weight:F2} 팔길이{Vector3.Distance(U.position,E.position)+Vector3.Distance(E.position,P.position):F3} 어깨-목표{Vector3.Distance(U.position,target):F3}";
 var err=Solve(side,target,rot,weight);if(debugCount<6){debugCount++;report.topology.Add("IK "+side+" "+before+" → 손"+W(P)+" 오차"+err.ToString("F1")+"mm");}return err;
 }
 // 손 캡슐 근사(손바닥 r 20mm, 손가락 r 9mm): 틈 = 캡슐 표면–메시 최소 거리(음수면 닿음 이상), 관통 = 메시 안으로 들어간 최대 깊이(닫힌 메시만)
 static List<(Vector3 p,float r)> HandPoints(string side){var pts=new List<(Vector3,float)>();var palm=Find("Base Human"+side+"Palm");var digits=palm.GetComponentsInChildren<Transform>().Where(t=>t!=palm&&t.name.Contains("Digit")).ToArray();var bases=digits.Where(d=>d.parent==palm).ToArray();
  if(bases.Length>0){var c=bases.Aggregate(Vector3.zero,(a,b)=>a+b.position)/bases.Length;for(int i=0;i<=4;i++)pts.Add((Vector3.Lerp(palm.position,c,i/4f),.02f));}
  foreach(var d in digits){if(d.parent==palm)continue;for(int i=0;i<=2;i++)pts.Add((Vector3.Lerp(d.parent.position,d.position,i/2f),.009f));
   if(d.childCount==0||!d.GetChild(0).name.Contains("Digit")){var dir=(d.position-d.parent.position);pts.Add((d.position+dir*.8f,.008f));}}
  return pts;}
 static (float gap,float pen) HandVs(string side,IEnumerable<Geometry> set){float gap=float.PositiveInfinity,pen=0;var gs=set.ToList();if(gs.Count==0)return(-1,-1);foreach(var (p,r) in HandPoints(side))foreach(var g in gs){float d=g.Closed?g.SignedDistance(p):g.Distance(p);gap=Mathf.Min(gap,d-r);if(g.Closed)pen=Mathf.Max(pen,r-d);}return(gap*1000,Mathf.Max(0,pen)*1000);}
 static float PartGap(string side,IEnumerable<Geometry> set,bool palmOnly){var gs=set.ToList();if(gs.Count==0)return -1;float gap=float.PositiveInfinity;foreach(var (p,r) in HandPoints(side)){if(palmOnly!=(r>=.02f))continue;foreach(var g in gs)gap=Mathf.Min(gap,(g.Closed?g.SignedDistance(p):g.Distance(p))-r);}return gap*1000;}
 // 손바닥이 개머리판 안/너무 가까우면: 가장 가까운 표면 점에서 바깥(개머리판 중심과 반대) 방향으로 손바닥 반지름+3mm까지 밀 벡터(mod_stock 기준)
 static Vector3 PalmPush(){var gs=geo["stock"];if(gs.Count==0)return Vector3.zero;var slot=Find("mod_stock");Vector3 worst=Vector3.zero;float need=0;
  var center=Vector3.zero;int cn=0;foreach(var g in gs)foreach(var v in g.vertices){center+=g.transform.TransformPoint(v);cn++;}center/=Mathf.Max(1,cn);
  foreach(var (p,r) in HandPoints("R")){if(r<.02f)continue;float margin=.003f;foreach(var g in gs){var q=g.ClosestWorld(p);var d=(p-q);float dist=d.magnitude;var outward=dist>1e-5f?d/dist:(p-center).normalized;if(Vector3.Dot(outward,p-center)<0){outward=-outward;dist=-dist;}float n=r+margin-dist;if(n>need){need=n;worst=outward*n;}}}
  return slot.InverseTransformVector(worst);}
 static Vector3 ThumbTip(){var d=Find("Base HumanRDigit13");return d.position+(d.position-d.parent.position)*.8f;}
 // 탄창 구멍 검사: 끼운 탄창(프리팹 기본 자세)의 입구 위 단면 = 구멍. 움직이는 탄창의 점이 입구보다 위면 그 단면(+1.5mm) 안이어야 한다.
 static float wellEntry=float.NaN;static Bounds wellBox;
 static IEnumerable<Vector3> MagPoints(){foreach(var g in geo["magazine"])for(int i=0;i<g.vertices.Length;i+=3)yield return weapon.InverseTransformPoint(g.transform.TransformPoint(g.vertices[i]));}
 static void SetupWell(){if(geo["magazine"].Count==0)return;Restore();var pts=MagPoints().ToList();var fb=new Bounds(pts[0],Vector3.zero);foreach(var p in pts)fb.Encapsulate(p);
  float entry=float.PositiveInfinity;foreach(var g in geo["solid"])for(int i=0;i<g.vertices.Length;i++){var w=weapon.InverseTransformPoint(g.transform.TransformPoint(g.vertices[i]));if(w.x>fb.min.x+.002f&&w.x<fb.max.x-.002f&&w.y>fb.min.y+.002f&&w.y<fb.max.y-.002f&&w.z>fb.min.z&&w.z<fb.max.z+.02f)entry=Mathf.Min(entry,w.z);}
  wellEntry=entry;var top=pts.Where(p=>p.z>entry).ToList();wellBox=new Bounds(top[0],Vector3.zero);foreach(var p in top)wellBox.Encapsulate(p);wellBox.Expand(new Vector3(.003f,.003f,0));
  report.topology.Add("탄창 구멍: 입구 z "+(entry*1000).ToString("F1")+"mm, 단면 x "+(wellBox.min.x*1000).ToString("F1")+".."+(wellBox.max.x*1000).ToString("F1")+" y "+(wellBox.min.y*1000).ToString("F1")+".."+(wellBox.max.y*1000).ToString("F1")+"mm");}
 static void MagWell(Sample s){if(float.IsNaN(wellEntry)||float.IsInfinity(wellEntry))return;float worst=0,top=-1;foreach(var p in MagPoints()){top=Mathf.Max(top,(p.z-wellEntry)*1000);if(p.z<=wellEntry+.001f)continue;float dx=Mathf.Max(0,Mathf.Max(wellBox.min.x-p.x,p.x-wellBox.max.x)),dy=Mathf.Max(0,Mathf.Max(wellBox.min.y-p.y,p.y-wellBox.max.y));worst=Mathf.Max(worst,Mathf.Sqrt(dx*dx+dy*dy)*1000);}s.magWellOutsideMm=worst;s.magTopAboveEntryMm=top;}
 static Sample Evaluate(AnimationClip clip,float time,bool collisions){Restore();clip.SampleAnimation(model,time);var w=job.weights.FirstOrDefault(x=>x.name==clip.name);float first=WeightAt(w,time,w?.first);var s=new Sample{time=time};float lweight=1-WeightAt(w,time,w.left)*first;float rweight=1-WeightAt(w,time,w.right)*first;s.ikErrorMm=Mathf.Max(Hand("L",lweight,out s.leftGripWeight),Hand("R",rweight,out s.rightGripWeight));var lp=Find("Base HumanLPalm");var rp=Find("Base HumanRPalm");s.leftSurfaceMm=geo["handguard"].Count>0?Geometry.Surface(lp.position,geo["handguard"])*1000:-1;s.magPalmMm=geo["magazine"].Count>0?Geometry.Surface(lp.position,geo["magazine"])*1000:-1;s.thumbSelectorMm=geo["selector"].Count>0?Geometry.Surface(Find("Base HumanRDigit13").position,geo["selector"])*1000:-1;
 {var a=HandVs("L",geo["handguard"]);s.lHandGuardGapMm=a.gap;var b=HandVs("L",geo["magazine"]);s.lHandMagGapMm=b.gap;var c=HandVs("L",geo["solid"].Concat(geo["handguard"]).Concat(geo["stock"]));s.lHandPenMm=c.pen;var d=HandVs("R",geo["stock"]);s.rHandStockGapMm=d.gap;s.rPalmStockGapMm=PartGap("R",geo["stock"],true);s.rPalmPushStockLocal=PalmPush();s.rFingerStockGapMm=PartGap("R",geo["stock"],false);var e=HandVs("R",geo["solid"].Concat(geo["stock"]).Concat(geo["handguard"]));s.rHandPenMm=Mathf.Max(e.pen,d.pen);s.rThumbTipSelectorMm=geo["selector"].Count>0?Geometry.Surface(ThumbTip(),geo["selector"])*1000:-1;}
 if(clip.name.Contains("stock_")){foreach(var g in geo["stock"].Concat(geo["solid"]))s.rightStockSphereMm=Mathf.Max(s.rightStockSphereMm,g.SpherePenetration(rp.position,.04f)*1000);}
 MagWell(s);
 if(false&&collisions&&clip.name.Contains("mag_")){foreach(var mag in geo["magazine"])foreach(var solid in geo["solid"].Concat(geo["handguard"])){var p=mag.CheckAgainst(solid,.001f);s.magPenetrationLowerMm=Mathf.Max(s.magPenetrationLowerMm,p.lower*1000);s.magPenetrationUpperMm=Mathf.Max(s.magPenetrationUpperMm,p.upper*1000);s.collisionUnresolved+=p.unresolved;}}
 return s;
 }
 static void Sheet(AnimationClip clip,string view){const int width=640,height=480;var sheet=new Texture2D(width*4,height*2,TextureFormat.RGB24,false);var cam=new GameObject("ValidationCamera").AddComponent<Camera>();cam.nearClipPlane=.01f;cam.farClipPlane=20;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.09f,.1f,.12f);var rt=new RenderTexture(width,height,24);cam.targetTexture=rt;
 for(int i=0;i<8;i++){Evaluate(clip,clip.length*Mathf.Lerp(job.sheetT0,job.sheetT1,i/7f),false);var look=weapon.TransformPoint(job.sheetLook);if(view=="fp"){var aim=Find("aim_camera");cam.orthographic=false;cam.fieldOfView=65;cam.fieldOfView=55;cam.transform.rotation=Quaternion.LookRotation(weapon.TransformDirection(Vector3.down),weapon.TransformDirection(Vector3.forward));cam.transform.position=aim.position-cam.transform.forward*.08f;}else{cam.orthographic=true;cam.orthographicSize=job.sheetSize;cam.transform.position=look+weapon.TransformDirection(new Vector3(view=="right"?1:-1,.08f,.12f));cam.transform.rotation=Quaternion.LookRotation(look-cam.transform.position,weapon.TransformDirection(Vector3.forward));}var balls=new List<GameObject>();foreach(var (bn,col) in new[]{("Base HumanLPalm",Color.blue),("Base HumanRPalm",Color.red)}){var bo=GameObject.CreatePrimitive(PrimitiveType.Sphere);UnityEngine.Object.DestroyImmediate(bo.GetComponent<Collider>());bo.transform.position=Find(bn).position;bo.transform.localScale=Vector3.one*.03f;bo.GetComponent<Renderer>().sharedMaterial=new Material(Shader.Find("Unlit/Color")){color=col};balls.Add(bo);}var baked=new List<GameObject>();var smrs=skin.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(x=>x.enabled).ToArray();foreach(var smr in smrs){try{var bm=new Mesh();smr.BakeMesh(bm,true);var go=new GameObject("baked");go.transform.SetPositionAndRotation(smr.transform.position,smr.transform.rotation);go.AddComponent<MeshFilter>().sharedMesh=bm;go.AddComponent<MeshRenderer>().sharedMaterials=smr.sharedMaterials;baked.Add(go);smr.enabled=false;}catch(Exception ex){report.topology.Add("BakeMesh 실패 "+smr.name+" "+ex.Message);}}
 cam.Render();foreach(var bo in balls)UnityEngine.Object.DestroyImmediate(bo);foreach(var go in baked)UnityEngine.Object.DestroyImmediate(go);foreach(var smr in smrs)smr.enabled=true;RenderTexture.active=rt;sheet.ReadPixels(new Rect(0,0,width,height),i%4*width,(1-i/4)*height);}
 sheet.Apply();var name=clip.name+"-"+view+".png";File.WriteAllBytes(Path.Combine(output,name),sheet.EncodeToPNG());report.renders.Add(name);RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(sheet);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(cam.gameObject);
 }
 public static void Run(){output=Arg("-k2Out");if(Directory.Exists(output))throw new Exception("Output already exists");Directory.CreateDirectory(output);report=new Report();try{Geometry.SelfTest();report.geometrySelfTest=true;job=JsonUtility.FromJson<Job>(File.ReadAllText(Arg("-k2Job")));report.name=job.name;Setup();var clips=Load(job.animation).LoadAllAssets<AnimationClip>();foreach(string name in job.clips){var clip=clips.Single(c=>c.name==name);var cr=new ClipResult{name=name};int n=job.probeOnly?7:Mathf.CeilToInt(clip.length*30);for(int i=0;i<=n;i++){float t=job.probeOnly?clip.length*i/n:Mathf.Min(i/30f,clip.length);cr.frames.Add(Evaluate(clip,t,!job.probeOnly));}report.clips.Add(cr);foreach(var view in (job.sheetViews!=null&&job.sheetViews.Length>0?job.sheetViews:new[]{"right","left","fp"}))Sheet(clip,view);File.WriteAllText(Path.Combine(output,"progress.json"),JsonUtility.ToJson(report,true));Debug.Log("VALIDATED "+name);}report.complete=!job.probeOnly;}catch(Exception e){report.error=e.ToString();Debug.LogException(e);}File.WriteAllText(Path.Combine(output,"report.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(string.IsNullOrEmpty(report.error)?0:1);}
}
